/** ESQUEMA DE LA CABECERA DEL COTIZADOR **/
CREATE COLUMN TABLE "GC_COPLAIM"."COTI" (
   "ID_COTI" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "IDENTITY" NVARCHAR(50) CS_STRING NOT NULL,
   "COD_CLIENT" NVARCHAR(50) CS_STRING NOT NULL,
   "RUC" NVARCHAR(50) CS_STRING NOT NULL,
   "CLIENTE" NVARCHAR(150) CS_STRING NOT NULL,
   "TELEFONO" NVARCHAR(15) CS_STRING,
   "EMAIL" NVARCHAR(150) CS_STRING,
   "CIA" NVARCHAR(150) CS_STRING DEFAULT 'CartomanabiSA',
   "CIUDAD" NVARCHAR(100) CS_STRING,
   "DIRECCION" NVARCHAR(100) CS_STRING,
   "PLAZO" NVARCHAR(20) CS_STRING NOT NULL,
   "PEDIDO" BOOLEAN CS_INT DEFAULT TRUE,
   "CLI_TRO" BOOLEAN CS_INT DEFAULT TRUE,
   "NOT_EMAIL" BOOLEAN CS_INT DEFAULT FALSE,
   "NOT_WHATS" BOOLEAN CS_INT DEFAULT FALSE,
   "SUB_CERO" DOUBLE CS_DOUBLE NOT NULL,
   "SUB_DOCE" DOUBLE CS_DOUBLE NOT NULL,
   "IVA" DOUBLE CS_DOUBLE NOT NULL,
   "TOTAL" DOUBLE CS_DOUBLE NOT NULL,
   "VENDEDOR" NVARCHAR(50) CS_STRING NOT NULL,
   "ESTADO" NVARCHAR(50) CS_STRING DEFAULT 'A',
   "USER" NVARCHAR(50) CS_STRING NOT NULL,
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

/** ESQUEMA DE LOS ITEMS EL COTIZADOR **/
CREATE COLUMN TABLE "GC_COPLAIM"."DOCOTI" (
   "ID_DOCOTI" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   "ID_COTI" INTEGER CS_INT NOT NULL,
   "CODE_PT" NVARCHAR(20) CS_STRING NOT NULL,
   "PRODUCTO" NVARCHAR(150) CS_STRING NOT NULL,
   "CANTIDAD" INTEGER CS_INT NOT NULL,
   "ALTO" INTEGER CS_INT,
   "LARGO" INTEGER CS_INT,
   "ANCHO" INTEGER CS_INT,
   "COD_MERCADO" NVARCHAR(20) CS_STRING,
   "MERCADO" NVARCHAR(150) CS_STRING,
   "TIPO" NVARCHAR(20) CS_STRING,
   "TEST" NVARCHAR(10) CS_STRING,
   "FLAUTA" NVARCHAR(5) CS_STRING,
   "ECT" INTEGER CS_INT,
   "COLOR_BOX" NVARCHAR(20) CS_STRING,
   "FACTOR" DOUBLE CS_DOUBLE,
   "PRE_MINIMO" DOUBLE CS_DOUBLE,
   "PRE_MINIMO_BRD" DOUBLE CS_DOUBLE,
   "PRE_SUGERIDO" DOUBLE CS_DOUBLE,
   "PRE_SUGERIDO_BRD" DOUBLE CS_DOUBLE,
   "PRE_MANUAL" DOUBLE CS_DOUBLE,
   "PRE_MANUAL_BRD" DOUBLE CS_DOUBLE,
   "SELECT_PRE" NVARCHAR(15) CS_STRING,
   "PRE_MIN_CALC" DOUBLE CS_DOUBLE,
   "PRE_SUG_CALC" DOUBLE CS_DOUBLE,
   "PRE_MAN_CALC" DOUBLE CS_DOUBLE,
   "PRECIO" DOUBLE CS_DOUBLE,
   "CHECK_TROQ" BOOLEAN CS_INT DEFAULT FALSE,
   "TROQUEL_CALC" DOUBLE CS_DOUBLE,
   "TROQUEL_MANL" DOUBLE CS_DOUBLE,
   "CHECK_CLI" BOOLEAN CS_INT DEFAULT FALSE,
   "COLOR" INTEGER CS_INT,
   "LARGO_IMP" INTEGER CS_INT,
   "ANCHO_IMP" INTEGER CS_INT,
   "CLISE_CALC" DOUBLE CS_DOUBLE,
   "CLISE_MANL" DOUBLE CS_DOUBLE,
   "LLEVA_IVA" BOOLEAN CS_INT DEFAULT FALSE,
   "IVA" DOUBLE CS_DOUBLE,
   "ESTUCADO" NVARCHAR(20) CS_STRING,
   "CREATED_AT" LONGDATE CS_LONGDATE NOT NULL,
   "UPDATED_AT" LONGDATE CS_LONGDATE NOT NULL
);

ALTER TABLE "GC_COPLAIM"."DOCOTI" ADD CONSTRAINT "DOCOTI_FK_ID_COTI" FOREIGN KEY ("ID_COTI") REFERENCES "GC_COPLAIM"."COTI" ("ID_COTI")
   ON UPDATE RESTRICT
   ON DELETE RESTRICT;